(67,	3616,	'Jika seseorang menggigit lantas kedua gigi serinya tanggal',	' إذا عض رجلا فوقعت ثناياه'),
(67,	3617,	'Gigi diganti dengan gigi',	' السن بالسن'),
(67,	3618,	'Diyat jari jemari',	' دية الأصابع'),
